import{_ as a,o as s,c as n,a4 as t}from"./chunks/framework.DpieW3qv.js";const u=JSON.parse('{"title":"status","description":"","frontmatter":{},"headers":[],"relativePath":"cli/status.md","filePath":"cli/status.md","lastUpdated":null}'),i={name:"cli/status.md"};function r(o,e,l,p,c,d){return s(),n("div",null,[...e[0]||(e[0]=[t(`<h1 id="status" tabindex="-1">status <a class="header-anchor" href="#status" aria-label="Permalink to &quot;status&quot;">​</a></h1><p><strong>Main entry point for web producers.</strong> Interactive hub with loop: pick refresh → pick action → run → back to board. Producers should also learn the other <a href="/ocapi-docs.github.io/cli/#producer-commands">producer commands</a> for full control: pull, build, preview, push, replicate, commit.</p><p>Unified refresh dashboard for the active brand. Shows a short, focused list and lets you pick a refresh and run an action. Refresh labels include the go-live time from the campaign (e.g. <strong>r1 - 3pm</strong>, <strong>r2 - 3am</strong>).</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">              # Last 14 days + future; interactive hub with loop</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">make</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ALL=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # Show full list (no date window)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><h2 id="date-window" tabindex="-1">Date window <a class="header-anchor" href="#date-window" aria-label="Permalink to &quot;Date window&quot;">​</a></h2><p>By default only refreshes from the <strong>last 14 days</strong> through <strong>all future</strong> dates are shown, so you don&#39;t scroll through a long list of past dates. Use <code>make status ALL=1</code> to see every refresh.</p><p>When the window is applied, status shows a reminder: <code>Showing last 14 days + future (N total). Use make status ALL=1 for full list.</code></p><h2 id="interactive-hub" tabindex="-1">Interactive Hub <a class="header-anchor" href="#interactive-hub" aria-label="Permalink to &quot;Interactive Hub&quot;">​</a></h2><p>When you run <code>make status</code> in a terminal, it opens an interactive hub that loops:</p><ol><li><strong>Refresh picker</strong> — Shows list of refreshes (↑↓ to move, Enter to select). Each row shows date, refresh label with time (e.g. <code>r1 - 3pm</code>), name, and status. Your active refresh is marked <strong>← active</strong>.</li><li><strong>Action picker</strong> — After selecting a refresh, choose an action: <ul><li><strong>Preview + browse files</strong> — Generate preview and show file browser</li><li><strong>Push to staging</strong> — Sync to SFCC staging</li><li><strong>Commit to Git</strong> — Commit changes to Git</li><li><strong>Browse files only</strong> — Show data files (assets/*.json, refresh.json, ocapi-payload.json)</li><li><strong>Rebuild (force)</strong> — Force rebuild ignoring guards</li><li><strong>Generate email</strong> — Generate changeout email</li></ul></li><li><strong>Action execution</strong> — Runs the selected action</li><li><strong>Return to board</strong> — After action completes, returns to refresh picker</li></ol><p>Pressing <code>q</code> on the action picker returns to the refresh picker. Pressing <code>q</code> on the refresh picker exits.</p><p>Picking a refresh sets it as active; subsequent commands (<code>make build</code>, <code>make preview</code>, etc.) use it automatically.</p><h2 id="no-tty-fallback" tabindex="-1">No-TTY fallback <a class="header-anchor" href="#no-tty-fallback" aria-label="Permalink to &quot;No-TTY fallback&quot;">​</a></h2><p>When status runs without a TTY (e.g. piped output or CI), it falls back to a table view: Date, Name, Status, Next Step, plus registry summary and footer. The Next Step column shows go-live time when relevant (e.g. <code>→ live 2/12 12 AM</code>). No interactive hub is shown.</p><p>For scripts: <code>make status ARGS=&quot;--no-interactive&quot;</code> forces table-only output even in a TTY.</p><h3 id="example-tty-interactive-picker" tabindex="-1">Example: TTY (interactive picker) <a class="header-anchor" href="#example-tty-interactive-picker" aria-label="Permalink to &quot;Example: TTY (interactive picker)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</span></span>
<span class="line"><span>  LOFT | STATUS                                          Fri, Feb 14</span></span>
<span class="line"><span>━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━━</span></span>
<span class="line"><span>  LIVE = live on site · SYNCED = pushed to SFCC · UPDATED = new source data since last push; needs rebuild · READY = ready to push · BUILD = needs preview · NEW = not yet built</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  4 refreshes · 1 live · 1 synced · 1 ready · 1 to build</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Current: 2026-02-14 / r1 - 3pm</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Select a refresh and press Enter for actions (q to exit)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    2026-02-12  r1 - 3am   Post-V-Day Sale           ● LIVE</span></span>
<span class="line"><span>  ❯ 2026-02-14  r1 - 3pm   Valentine&#39;s Day            ✔ READY   ← active</span></span>
<span class="line"><span>    2026-02-15  r1 - 3am   Post-Valentine              ○ BUILD</span></span>
<span class="line"><span>    2026-02-20  r1 - 3pm   Presidents Day              · NEW</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br></div></div><h3 id="example-non-tty-table-output" tabindex="-1">Example: non-TTY (table output) <a class="header-anchor" href="#example-non-tty-table-output" aria-label="Permalink to &quot;Example: non-TTY (table output)&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>$ make status ARGS=&quot;--no-interactive&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  Status    Date         Refresh    Name                   Next Step</span></span>
<span class="line"><span>  ──────────────────────────────────────────────────────────────────</span></span>
<span class="line"><span>  LIVE      2026-02-12   r1 - 3am   Post-V-Day Sale        (live now)</span></span>
<span class="line"><span>  READY     2026-02-14   r1 - 3pm   Valentine&#39;s Day        make push</span></span>
<span class="line"><span>  BUILD     2026-02-15   r1 - 3am   Post-Valentine         make preview</span></span>
<span class="line"><span>  NEW       2026-02-20   r1 - 3pm   Presidents Day         make build</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><h2 id="sync-state-and-ocapi" tabindex="-1">Sync state and OCAPI <a class="header-anchor" href="#sync-state-and-ocapi" aria-label="Permalink to &quot;Sync state and OCAPI&quot;">​</a></h2><p>When OCAPI is enabled, <strong><code>make status</code> uses SFCC as the source of truth for sync state:</strong></p><ul><li>Refreshes that have no local sync record but exist on SFCC are shown as SYNCED/LIVE and local state is updated.</li><li>Refreshes that are marked SYNCED/LIVE locally are checked against SFCC; if the campaign no longer exists on SFCC, state is downgraded to READY and local sync config is updated.</li></ul><p>So after cloning the repo or moving to another machine, running <code>make status</code> once will align the dashboard with what’s actually on SFCC.</p><h2 id="states" tabindex="-1">States <a class="header-anchor" href="#states" aria-label="Permalink to &quot;States&quot;">​</a></h2><table tabindex="0"><thead><tr><th>State</th><th>Condition</th></tr></thead><tbody><tr><td><code>LIVE</code></td><td>Synced and date is today (currently live on site)</td></tr><tr><td><code>SYNCED</code></td><td>Synced and date is not today (ready for future go-live)</td></tr><tr><td><code>UPDATED</code></td><td>Previously synced but new source data since last push (needs rebuild)</td></tr><tr><td><code>READY</code></td><td><code>ocapi-payload.json</code> exists, not yet pushed</td></tr><tr><td><code>BUILD</code></td><td><code>refresh.json</code> exists but no payload</td></tr><tr><td><code>NEW</code></td><td>Data fetched, not yet built (same as BUILD)</td></tr></tbody></table><p>Definitions are canonical in <a href="/ocapi-docs.github.io/glossary.html#status-states">Glossary — Status States</a>. Status uses <strong>local</strong> sync state first (from <code>sync-config.json</code> in each refresh folder). When <strong>OCAPI is enabled</strong>, it also checks SFCC: if a refresh&#39;s campaign exists on the site, that row is shown as SYNCED or LIVE even when local state is missing (e.g. after deleting dev-env). Any state learned from SFCC is <strong>written back to local</strong> automatically, so the next run (or build guards) can use it without re-querying SFCC.</p><h2 id="help" tabindex="-1">Help <a class="header-anchor" href="#help" aria-label="Permalink to &quot;Help&quot;">​</a></h2><p>Every command supports <code>--help</code> for detailed usage:</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src/cli/index.js</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --help</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>The Makefile remains the normal entrypoint (<code>make status</code>). Direct <code>node</code> usage is supported for debugging and scripting.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/ocapi-docs.github.io/cli/">CLI Reference</a> — all producer and dev commands</li><li><a href="/ocapi-docs.github.io/cli/pull.html">pull</a></li><li><a href="/ocapi-docs.github.io/cli/select.html">select</a> — direct switching (scripts, <code>DATE=</code>) without opening the dashboard</li><li><a href="/ocapi-docs.github.io/guides/producer-workflow.html">Producer workflow</a></li></ul>`,33)])])}const b=a(i,[["render",r]]);export{u as __pageData,b as default};
